package com.wailsvlr.prism.modules;

import com.wailsvlr.prism.gui.Notifications;
import com.wailsvlr.prism.gui.Pointers;
import com.wailsvlr.prism.module.Category;
import com.wailsvlr.prism.module.Module;
import com.wailsvlr.prism.render.Highlight;
import com.wailsvlr.prism.render.HighlightStyle;
import com.wailsvlr.prism.setting.BoolSetting;
import net.minecraft.ChatFormatting;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.ClickEvent;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.HoverEvent;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import java.util.List;

/** Remembers where you died: the coordinates in chat (click to copy), a beam at the spot and an arrow back to it. */
public class DeathPoint extends Module {
	private final BoolSetting chat, pointer, beam, clearOnReach;
	private volatile BlockPos pos;
	private volatile ResourceKey<Level> dim;
	private boolean dead;

	public DeathPoint() {
		super("DeathPoint", "Remembers where you died: coordinates in chat (click to copy), a beam at the spot and an arrow pointing back", Category.MISC);
		chat = add(new BoolSetting("Chat Message", "Write the coordinates in chat when you die (click the message to copy them)", true));
		pointer = add(new BoolSetting("Pointer", "An arrow around the crosshair pointing back to where you died", true));
		beam = add(new BoolSetting("Beam", "A tall column and a label at the spot, visible through walls", true));
		clearOnReach = add(new BoolSetting("Clear On Reach", "Forget the spot once you are back within 3 blocks of it", true));
	}

	@Override
	public void onTick() {
		if (mc.player == null || mc.level == null) return;
		boolean d = mc.player.isDeadOrDying();
		if (d && !dead) {
			pos = mc.player.blockPosition();
			dim = mc.level.dimension();
			announce();
		}
		dead = d;
		BlockPos p = pos;
		if (p != null && !d && clearOnReach.isOn() && mc.level.dimension() == dim && mc.player.blockPosition().distSqr(p) <= 9) {
			Notifications.post("deathpoint", "check", "DeathPoint", "You are back where you died");
			pos = null;
		}
	}

	private static String dimName(ResourceKey<Level> k) {
		return k == Level.OVERWORLD ? "Overworld" : k == Level.NETHER ? "Nether" : k == Level.END ? "End" : k.identifier().getPath();
	}

	private void announce() {
		String xyz = pos.getX() + " " + pos.getY() + " " + pos.getZ();
		if (chat.isOn()) {
			Component c = Component.literal("[Legit] ").withStyle(ChatFormatting.LIGHT_PURPLE)
				.append(Component.literal("You died at ").withStyle(ChatFormatting.WHITE))
				.append(Component.literal(xyz).withStyle(s -> s.withColor(ChatFormatting.AQUA).withUnderlined(true)
					.withClickEvent(new ClickEvent.CopyToClipboard(xyz))
					.withHoverEvent(new HoverEvent.ShowText(Component.literal("Click to copy")))))
				.append(Component.literal(" (" + dimName(dim) + ")").withStyle(ChatFormatting.GRAY));
			mc.gui.getChat().addClientSystemMessage(c);
		}
		Notifications.post("deathpoint", "pin", "DeathPoint", "Died at " + xyz + " (" + dimName(dim) + ")");
	}

	private boolean here() {
		return pos != null && mc.level != null && mc.level.dimension() == dim;
	}

	public Pointers.Target pointerTarget() {
		if (!isEnabled() || !pointer.isOn() || !here() || dead) return null;
		return new Pointers.Target(Vec3.atCenterOf(pos), "Death point", 0xF0F0F0);
	}

	public void collect(List<Highlight> out) {
		if (!isEnabled() || !beam.isOn() || !here() || mc.player == null) return;
		BlockPos p = pos;
		HighlightStyle st = new HighlightStyle("Both", 0.9f, 0.25f, 2f, true, false, 0, false, 100000, true, 0.6f, 0, false);
		int dist = (int) Math.round(Math.sqrt(p.distToCenterSqr(mc.player.position())));
		out.add(new Highlight(new AABB(p), 0xF0F0F0, st, "Death point " + dist + "m"));
		out.add(new Highlight(new AABB(p.getX() + 0.4, p.getY() + 1, p.getZ() + 0.4, p.getX() + 0.6, p.getY() + 48, p.getZ() + 0.6), 0xF0F0F0,
			new HighlightStyle("Fill", 0, 0.35f, 1f, true, false, 0, false, 100000, false, 1, 0, false), null));
	}

	/** For the tests. */
	public BlockPos last() { return pos; }
}
